"""Concise original summaries of specifically verified primary reports."""
import json
from content import ROOT, slug

def hadith(reference):
    collection,number=reference.split(':')
    return dict(label=f"{'Sahih al-Bukhari' if collection=='bukhari' else 'Sahih Muslim'} {number}",url=f'https://sunnah.com/{reference}',kind='Hadith report')

# Year bands are navigation aids. The report supports the event, not necessarily
# the conventional CE/AH placement. Disputed ordering is stated separately.
EVENTS=[
 (610,'c. 610 CE','Early Makkah','Revelation','Hira','The first revelation','Aisha\'s report places the beginning of revelation in the cave of Hira, following a period of meaningful dreams and seclusion.','bukhari:3','The report supplies the setting; the CE year is conventional and approximate.'),
 (610,'c. 610 CE','Early Makkah','Character','Makkah','Khadija offers reassurance','After the experience at Hira, Khadija reassured the Prophet ﷺ by recalling his care for relatives, guests, and people in difficulty.','bukhari:3','A sequence within the first-revelation report, rather than a separately dated event.'),
 (610,'c. 610 CE','Early Makkah','Revelation','Makkah','A conversation with Waraqa','Khadija brought the account to Waraqa ibn Nawfal, who connected the experience with earlier revelation and anticipated opposition.','bukhari:3','The report describes the sequence without a calendar date.'),
 (611,'Early mission','Early Makkah','Revelation','Makkah','Revelation after a pause','Jabir\'s report describes revelation resuming after a pause and associates the moment with the opening instructions of Al-Muddaththir.','bukhari:4','Exact length of the pause and CE date are not established here.'),
 (613,'Early mission','Early Makkah','Community','Safa','Calling the clans at Safa','Ibn Abbas reports that the Prophet ﷺ gathered the clans at Safa and warned them publicly. Their answer acknowledged his previous truthfulness.','bukhari:4770','Commonly placed in the early public mission; the report itself gives no CE year.'),
 (615,'Makkan period','Early Makkah','Resilience','Makkah','Khabbab asks for help','Khabbab recalled asking for help during persecution. The reported reply placed their suffering alongside the endurance of earlier believers.','bukhari:3852','A broad Makkan placement is used because this report does not date the exchange.'),
 (616,'Makkan period','Early Makkah','Community','Makkah','Abu Bakr and protection','Aisha\'s report describes Ibn al-Daghina offering Abu Bakr protection, disputes about public worship, and Abu Bakr later releasing him from that agreement.','bukhari:3905','The episode predates the Hijrah, but the precise CE year is not supplied.'),
 (620,'Late Makkan period','Late Makkah','Mercy','Taif region','A difficult encounter and a merciful response','When recalling a painful rejection, the Prophet ﷺ described declining an offer of destruction and hoping for future generations who would worship Allah.','bukhari:3231','Often associated with the Taif journey. The report names locations but gives no CE date.'),
 (621,'Before the Hijrah','Late Makkah','Worship','Makkah','The Night Journey and ascent','The report of Malik ibn Sasaa describes the Night Journey and ascent, including the prescription of prayer.','bukhari:3887','The exact date is disputed. Its position here is a broad pre-Hijrah placement, not a fixed anniversary.'),
 (621.5,'Before the Hijrah','Late Makkah','Community','Aqabah','The pledges at Aqabah','Ubada ibn al-Samit is identified as an Aqabah participant and reports a pledge covering worship and conduct.','bukhari:18','This report identifies a participant and a pledge; it does not by itself establish every detail of the two Aqabah meetings.'),
 (622,'1 AH · c. 622 CE','Hijrah','Migration','Near Makkah','The cave during the migration','Abu Bakr recalls concern that pursuers might see them in the cave and the Prophet\'s reassurance. Quran 9:40 also refers to the two in the cave.','bukhari:3653','The Hijrah is conventionally dated to 622 CE. The report quoted here does not name the cave.'),
 (622.1,'1 AH · c. 622 CE','Hijrah','Migration','Migration route','Suraqa on the route','Suraqa\'s account describes pursuing the travelers, his horse stumbling, and his eventual request for a written assurance of safety.','bukhari:3906','The report supplies the episode; this schematic view does not reconstruct the exact route.'),
 (622.2,'1 AH · c. 622 CE','Hijrah','Community','Madinah','Arrival among Banu Amr ibn Awf','Anas reports an initial stay among Banu Amr ibn Awf, followed by a welcome from Banu al-Najjar and arrival at Abu Ayyub\'s courtyard.','bukhari:428','Relative sequence is clearer than an exact Gregorian day.'),
 (622.3,'1 AH · c. 622 CE','Early Madinah','Worship','Madinah','Building the mosque','Anas describes preparing a site for the mosque in Madinah and the community\'s involvement in the work.','bukhari:428','Shown after arrival. The cited report is the evidence for the construction episode.'),
 (622.4,'Early Madinan period','Early Madinah','Community','Madinah','Brotherhood and a market','The report pairs Abd al-Rahman ibn Awf with Sad ibn al-Rabi. It records Sad\'s generous offer and Abd al-Rahman\'s request to be shown the market.','bukhari:3780','The report places the episode after the emigrants reached Madinah; no exact date is supplied.'),
 (624,'2 AH · c. 624 CE','Early Madinah','Worship','Madinah','The change of qiblah','Al-Bara reports prayer toward Jerusalem for sixteen or seventeen months, followed by the change toward the Kaaba.','bukhari:399','The narrator preserves a sixteen-or-seventeen-month uncertainty; the app keeps that uncertainty.'),
 (624.2,'2 AH · c. 624 CE','Early Madinah','Expeditions','Badr','Supplication at Badr','Ibn Abbas reports the Prophet\'s earnest supplication at Badr and Abu Bakr\'s presence. Quran 3:123 explicitly names Badr.','bukhari:3953','The conventional year is a chronology aid. The report is cited for the supplication, not a complete battle narrative.'),
 (625,'3 AH · c. 625 CE','Early Madinah','Expeditions','Uhud','The archers at Uhud','Al-Bara describes the instructions given to the archers under Abdullah ibn Jubayr and the consequences of leaving their position.','bukhari:3039','The conventional year is approximate in CE terms; details follow the named report.'),
 (625.1,'3 AH · c. 625 CE','Early Madinah','Expeditions','Uhud','A report on the retreat','A second report from Al-Bara identifies the archers\' commander and recalls the retreat during Uhud.','bukhari:4067','A separate report about the same battle, not another battle or an independently dated event.'),
 (627,'5 AH · c. 627 CE','Later Madinah','Community','Madinah','Digging the trench','Anas recalls the emigrants and helpers carrying earth while digging the trench, with hunger and difficult food supplies during the work.','bukhari:4100','The trench campaign is conventionally placed in 5 AH; the cited report describes the labor.'),
 (627.2,'Madinan period · date debated','Later Madinah','Community','Madinah','The account of the slander','Aisha\'s extended report recounts the false accusation against her and the distress and eventual resolution that followed.','bukhari:4141','Its relation to some campaigns is debated. Placement in this band is approximate, not a claim of a precise year.'),
 (628,'6 AH · c. 628 CE','Later Madinah','Treaties','Hudaybiyah','The journey to Hudaybiyah','Al-Miswar and Marwan\'s account describes a journey intended for Umrah, negotiations with Quraysh, and the eventual agreement.','bukhari:2731','Conventional 6 AH placement. The linked report contains the detailed sequence.'),
 (628.1,'6 AH · c. 628 CE','Later Madinah','Treaties','Hudaybiyah','The pledge beneath the tree','Jabir recalls the group at Hudaybiyah and identifies the tree associated with the pledge. Quran 48:18 explicitly mentions the pledge beneath a tree.','bukhari:4154','Jabir gives a group count in this report. Other transmitted counts should not be silently harmonized.'),
 (628.2,'6 AH · c. 628 CE','Later Madinah','Treaties','Hudaybiyah','Negotiating the written agreement','The Hudaybiyah account records negotiations and the writing of treaty terms. Its difficult concessions form part of the report\'s sequence.','bukhari:2731','A detail of the same treaty episode, not a separate treaty.'),
 (628.4,'7 AH · c. 628 CE','Later Madinah','Expeditions','Khaybar','The banner at Khaybar','Sahl ibn Sad reports the announcement about the banner at Khaybar and its being given to Ali ibn Abi Talib.','bukhari:4210','The conventional year is shown; the linked report supports the banner episode.'),
 (628.5,'After Hudaybiyah','Later Madinah','Diplomacy','Outside Arabia','A letter and questions from Heraclius','Abu Sufyan\'s account describes Heraclius questioning him during the truce with Quraysh and a letter from the Prophet ﷺ.','bukhari:7','The report explicitly situates the exchange during the truce. The CE placement is approximate.'),
 (629,'7 AH · c. 629 CE','Later Madinah','Worship','Makkah','The return for Umrah','Al-Bara\'s report describes the agreement for a later visit to Makkah and a stay of three days under its terms.','bukhari:4251','The report links the visit to the agreement; its conventional chronology is 7 AH.'),
 (630,'8 AH · c. 630 CE','Later Madinah','Community','Makkah','The approach to Makkah','The report describes the approach during the year of the conquest and Abu Sufyan\'s encounter with the Muslim camp.','bukhari:4280','The year of the conquest is explicit in the report. CE conversion is approximate.'),
 (630.1,'8 AH · c. 630 CE','Later Madinah','Worship','Makkah','The Kaaba at the conquest','Abdullah reports the removal of idols around the Kaaba when the Prophet ﷺ entered Makkah.','bukhari:4287','A detail of the conquest episode. No depictions of the Prophet are used.'),
 (630.2,'8 AH · c. 630 CE','Later Madinah','Expeditions','Hunayn','Steadfastness at Hunayn','Al-Bara reports that the Prophet ﷺ did not flee at Hunayn, while some people hurried away under the opposing archers\' attack.','bukhari:4315','The conventional placement follows the conquest; the report supports this specific observation.'),
 (630.6,'9 AH · c. 630 CE','Later Madinah','Expeditions','Tabuk','The expedition to Tabuk','Kab ibn Malik\'s account describes his failure to join the expedition to Tabuk and the circumstances that followed.','bukhari:4418','Shown in the conventional 9 AH band. Read the complete report for its longer sequence.'),
 (630.7,'After Tabuk','Later Madinah','Character','Madinah','Kab ibn Malik tells the truth','Kab\'s account contrasts his truthful admission with the excuses he might have offered and recounts the eventual acceptance of repentance.','bukhari:4418','Part of the same report as Tabuk. Its relative sequence is more important here than an exact CE day.'),
 (631,'9 AH · c. 631 CE','Later Madinah','Worship','Mina','Announcements during Abu Bakr\'s Hajj','Abu Hurayra recalls being sent among the announcers at the Hajj led by Abu Bakr. The report also mentions Ali reciting Baraah.','bukhari:4655','Conventionally placed in 9 AH, before the Prophet\'s Farewell Hajj.'),
 (632,'10 AH · 632 CE','Final year','Worship','Arafat','The Farewell Hajj','Jabir\'s long report describes the announced pilgrimage in the tenth year, its journey, rites, and the address at Arafat.','muslim:1218a','The report explicitly identifies the tenth year in Madinah. Individual Gregorian date conversions are not asserted.'),
 (632.1,'10 AH · 632 CE','Final year','Community','Mina','Conveying the message','Abu Bakra reports an address on the Day of Nahr emphasizing the sanctity of life and property and conveying the message to those absent.','bukhari:1741','This report concerns the address at Mina; it is not silently merged with every other Farewell Hajj sermon.'),
 (632.5,'11 AH · 632 CE','Final year','Community','Madinah','The death of the Prophet ﷺ','Aisha describes his final moments in her home. Another report records Abu Bakr addressing the community afterward and reciting Quran 3:144.','bukhari:4449','The year is conventional. The report supports the setting of the final moments; see the additional report for the community response.'),
]
events=[]
for i,(year,date,era,topic,place,title,summary,reference,uncertainty) in enumerate(EVENTS):
    sources=[hadith(reference)]
    if i==35:sources.append(hadith('bukhari:4452'))
    events.append(dict(id=slug(title),number=i+1,year=year,date=date,era=era,topic=topic,place=place,title=title,summary=summary,sources=sources,uncertainty=uncertainty))
assert len(events)==36

# Evidence descriptions are concise paraphrases, clearly distinct from quotations.
CASES=[
 ('The first witness','Early Makkah','Revelation','bukhari:3','Aisha\'s account takes us from Hira to a household conversation. Which sequence does the report support?',
  [('A place of seclusion','The account identifies Hira as the setting of the first encounter.'),('A trusted response','Khadija reassures him after hearing what happened.'),('A further conversation','Khadija takes the account to Waraqa ibn Nawfal.')],
  ['Hira, then Khadija\'s reassurance, then Waraqa.','Waraqa is present inside the cave.','The report gives an exact Gregorian day.'],
  'The report supports that sequence. It does not place Waraqa in Hira or provide an exact Gregorian date.','Follow the movement from the cave to the conversations afterward.'),
 ('The gathering at Safa','Early Makkah','Public mission','bukhari:4770','A gathering tests what the clans already know about the speaker. What can be established from Ibn Abbas\'s report?',
  [('A public summons','The Prophet ﷺ calls clans of Quraysh to Safa.'),('A question about trust','He asks whether they would believe a warning about approaching cavalry.'),('The response','Their reply acknowledges his truthfulness before the warning.')],
  ['The warning draws on an acknowledged record of truthfulness.','Every person present immediately accepts the message.','The report identifies the exact year of the gathering.'],
  'The report supports the acknowledgment of truthfulness. It does not say everyone accepted, and it supplies no exact CE year.','Separate what the audience says about trust from how every individual responds.'),
 ('After the rejection','Late Makkah','Mercy','bukhari:3231','Aisha asks about a particularly difficult experience. Which response is actually described?',
  [('The painful encounter','The report recalls rejection after approaching Ibn Abd Yalail.'),('An offered action','The Angel of the Mountains offers to bring the mountains down.'),('The response','The Prophet ﷺ declines and expresses hope for future descendants.')],
  ['He declines destruction and hopes for future worshippers.','The offered destruction is carried out immediately.','The report gives an exact date for an annual observance.'],
  'The stated response is hope for descendants, not the destruction offered. No exact anniversary is established by this report.','Distinguish the offer from the answer to it.'),
 ('Two in the cave','Hijrah','Migration','bukhari:3653','Abu Bakr describes a moment of danger during the migration. Which conclusion stays within this brief report?',
  [('The narrator','Abu Bakr recounts being in the cave with the Prophet ﷺ.'),('The concern','He fears that looking down would let the pursuers see them.'),('The reassurance','The reported reply reassures Abu Bakr about Allah\'s presence with them.')],
  ['The report records concern followed by reassurance.','This report describes a spider spinning a web.','This report names every person involved in the route.'],
  'The brief report establishes the concern and reassurance. It does not mention a spider\'s web or provide a full route list.','Avoid importing familiar details that are not present in the cited report.'),
 ('The pursuer\'s request','Hijrah','Migration','bukhari:3906','Suraqa pursues the travelers, but the encounter changes. What does he request before they continue?',
  [('A pursuit','Suraqa describes setting out after the travelers.'),('A changed situation','He recounts his horse stumbling and later sinking at the forelegs.'),('A written assurance','He asks for a statement of safety, which Amr ibn Fuhayra writes.')],
  ['A written assurance of safety.','A declaration that every future pursuer has already converted.','A complete map of the remaining journey.'],
  'The report specifies a written assurance of safety. The other conclusions add claims not made in these evidence cards.','Look for the request made after Suraqa approaches them.'),
 ('Where is the market?','Early Madinah','Community','bukhari:3780','A report about brotherhood includes a generous offer and an independent response. What does Abd al-Rahman ask for?',
  [('A bond','The account pairs Abd al-Rahman ibn Awf with Sad ibn al-Rabi.'),('An offer','Sad offers substantial help from his property.'),('The reply','Abd al-Rahman offers a blessing and asks to be shown the market.')],
  ['To be shown the market.','To be appointed ruler of the city.','To forbid anyone else from trading.'],
  'The report identifies the market request and subsequent trading. It does not support the claims about political appointment or excluding other traders.','Focus on the reply to Sad\'s offer.'),
 ('A direction changes','Early Madinah','Worship','bukhari:399','News reaches people who are already praying. Which detail should a careful reader preserve?',
  [('An earlier direction','Al-Bara describes prayer toward Jerusalem.'),('A narrated uncertainty','The duration is given as sixteen or seventeen months.'),('New information','A person who prayed with the Prophet ﷺ conveys the new direction to others.')],
  ['The report preserves uncertainty between sixteen and seventeen months.','The report gives exactly sixteen months with no uncertainty.','The report says every prayer before the change was invalid.'],
  'The narrator\'s sixteen-or-seventeen wording should remain visible. The other answers either erase uncertainty or introduce an unsupported conclusion.','A small uncertainty is evidence too; do not edit it out.'),
 ('The archers\' instruction','Early Madinah','Uhud','bukhari:3039','The archers receive an instruction covering more than one possible outcome. What made leaving the position a problem?',
  [('A commander','Abdullah ibn Jubayr commands the archers in this report.'),('The instruction','They are told to remain until a message reaches them, even if either side appears to be winning.'),('A decision','Some leave after seeing an apparent victory and the prospect of spoils.')],
  ['The instruction explicitly covered an apparent victory as well as danger.','No instructions had been given about the position.','Every archer leaves and the report gives no exceptions.'],
  'The report makes the instruction explicit. An apparent victory did not cancel it. The absolute claim about every archer goes beyond these cards.','Read the condition about apparent victory, not just the condition about danger.'),
 ('The journey\'s purpose','Later Madinah','Hudaybiyah','bukhari:2731','Negotiators ask why the travelers have come. What purpose is stated in the Hudaybiyah account?',
  [('The journey','The account describes the approach to Hudaybiyah.'),('A stated purpose','The Prophet ﷺ explains that they have come for Umrah rather than to initiate fighting.'),('Negotiation','The narrative proceeds through messages and agreement terms.')],
  ['The stated purpose is Umrah, and negotiation follows.','The travelers state that they have come only for trade.','The report says no negotiation takes place.'],
  'The report explicitly distinguishes the intended Umrah from initiating battle. The existence of negotiation is part of the account.','Separate a stated purpose from later tensions during the journey.'),
 ('Who receives the banner?','Later Madinah','Khaybar','bukhari:4210','An announcement makes people wonder who will receive a banner. Which identification is supported?',
  [('An announcement','The banner is to be given the next morning to a person described favorably.'),('Anticipation','Those present hope to receive it.'),('The outcome','The report names Ali ibn Abi Talib as its recipient.')],
  ['Ali ibn Abi Talib receives the banner in this report.','The recipient is chosen by a public vote described here.','The report never identifies who receives it.'],
  'The report identifies Ali. Anticipation among the companions is not evidence of a public vote.','Look for the recorded outcome rather than the expectations beforehand.'),
 ('Questions during a truce','Later Madinah','Diplomacy','bukhari:7','Abu Sufyan describes an interview with Heraclius. What setting does the account explicitly preserve?',
  [('A narrator','Abu Sufyan reports the exchange to Ibn Abbas.'),('A period of truce','The account locates it during the truce between the Prophet ﷺ and Quraysh.'),('Questions and a letter','Heraclius asks questions, and the account includes the Prophet\'s letter.')],
  ['The interview occurs during the truce described by the narrator.','The report states that Heraclius publicly converts immediately.','The conversation happens before any prophetic mission begins.'],
  'The truce is explicit. The account should not be turned into an assertion of public conversion that it does not establish.','An interested response and a public conversion are different claims.'),
 ('News from a distant land','Later Madinah','Community','bukhari:1333','A death is announced, and a prayer follows. Which action is recorded in this report?',
  [('The news','Abu Hurayra recounts the announcement of al-Najashi\'s death.'),('The place','The group goes to the prayer ground and forms rows.'),('The prayer','The report records four takbirs in the funeral prayer.')],
  ['A funeral prayer in rows with four takbirs.','A journey by the entire group to attend a burial abroad.','An exact CE date is supplied in the report.'],
  'The report records the prayer and its four takbirs. It does not describe the group traveling abroad or give an exact Gregorian date.','Concentrate on what the group does after receiving the news.'),
]
cases=[]
for i,(title,era,topic,reference,brief,evidence,answers,conclusion,hint) in enumerate(CASES):
    source=hadith(reference)
    cases.append(dict(id=slug(title),number=i+1,title=title,era=era,topic=topic,brief=brief,evidence=[dict(id=f'e{j+1}',title=t,text=text,source=source) for j,(t,text) in enumerate(evidence)],answers=answers,correct=0,conclusion=conclusion,hint=hint,sources=[source]))
assert len(cases)==12
if __name__=='__main__':
    (ROOT/'_implementation/research/history-seed.json').write_text(json.dumps(dict(events=events,cases=cases),ensure_ascii=False,indent=2),encoding='utf-8')
    print(f'Wrote {len(events)} event records and {len(cases)} investigations.')
